        "src": "https://substackcdn.com/image/fetch/$s_!TFsv!,w_1456,c_limit,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F84f3fbab-da83-492c-8f16-3b982182ca47_528x351.png",
